create table if not exists public.applications (id bigint generated by default as identity primary key,name text not null check(char_length(name) between 2 and 150),course text not null,specialty text not null check(char_length(specialty) between 2 and 120),brigade text not null default '',contact text not null check(char_length(contact) between 2 and 150),goal text not null check(char_length(goal) between 5 and 3000),experience text default '',status text not null default 'pending' check(status in ('pending','review','accepted','rejected')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());create table if not exists public.admins (id uuid primary key references auth.users(id) on delete cascade,email text,created_at timestamptz not null default now());alter table public.applications enable row level security;alter table public.admins enable row level security;drop policy if exists "public can submit applications" on public.applications;create policy "public can submit applications" on public.applications for insert to anon,authenticated with check(true);drop policy if exists "admins can read applications" on public.applications;create policy "admins can read applications" on public.applications for select to authenticated using(exists(select 1 from public.admins where id=auth.uid()));drop policy if exists "admins can update applications" on public.applications;create policy "admins can update applications" on public.applications for update to authenticated using(exists(select 1 from public.admins where id=auth.uid())) with check(exists(select 1 from public.admins where id=auth.uid()));drop policy if exists "admins can read admin profile" on public.admins;create policy "admins can read admin profile" on public.admins for select to authenticated using(id=auth.uid());create index if not exists applications_status_idx on public.applications(status);create index if not exists applications_created_at_idx on public.applications(created_at desc);alter table public.applications add column if not exists brigade text not null default '';